add_action( 'woocommerce_before_shop_loop_item_title', 'perfectpixel_sold_out_badge', 4 );

function perfectpixel_sold_out_badge() {
	global $product;
	if ( $product && ! $product->is_in_stock() ) {
		echo '<span class="perfectpixel-sold-out" style="position:absolute;top:.5em;left:.5em;z-index:9;padding:.2em .6em;border-radius:3px;color:#fff;font-size:.8em;font-weight:600;background:#50575e">' . esc_html( '{{sold_out_badge_text}}' ) . '</span>';
	}
}
